"""Generate reviewed Chapter 4 checks; exact arithmetic and residual verification."""
import json
from pathlib import Path
import sympy as s
M=s.Matrix
Q={}
def tex(x):
 if isinstance(x,s.MatrixBase): return r'\begin{bmatrix}'+r'\\'.join(' & '.join(s.latex(z) for z in x.row(i)) for i in range(x.rows))+r'\end{bmatrix}'
 return s.latex(s.sympify(x))
def math(x):return r'\('+x+r'\)'
def mat(x):return math(tex(M(x)))
def tup(v):return '('+','.join(s.latex(z) for z in v)+')'
def basis(v):return math(r'\{'+', '.join(tup(x) for x in v)+r'\}') if v else math(r'\varnothing')
def key(sec,n):return f'anton-section-4-{sec}-{n}' if sec else f'anton-chapter-04-supplementary-{n}'
def add(sec,n,fields,notice=None):
 Q[key(sec,n)]={'fields':fields,'scope':'All source exercise parts; proof and construction requests are checked through concrete conclusions and worked reasoning.','complete':True,'sourceImageReviewed':True}
 if notice:Q[key(sec,n)]['reviewNotice']=notice
 save()
def save():Path('scripts/linear-answer-checks/ch04-reviewed.json').write_text(json.dumps({'chapter':4,'questions':Q},indent=2,ensure_ascii=False)+'\n')
def c(label,prompt,answer,wrong,steps):
 return {'label':label,'selectionPrompt':prompt,'type':'choice','answer':answer,'options':[answer]+[x for x in wrong if x!=answer],'explanation':steps[-1],'workedSteps':steps}
def num(label,prompt,answer,steps):return {'label':label,'selectionPrompt':prompt,'type':'numeric','answer':int(answer),'tolerance':0,'explanation':steps[-1],'workedSteps':steps}
def yn(label,prompt,yes,steps):return c(label,prompt,'Yes' if yes else 'No',['No' if yes else 'Yes'],steps)
def mc(label,prompt,answer,steps):
 A=M(answer);bad=A.copy();bad[0]+=1;bad2=-A
 if bad2==A:bad2=2*s.ones(*A.shape)
 return c(label,prompt,mat(A),[mat(bad),mat(bad2)],steps)
def proof(label,prompt,answer,wrong,steps):return c(label,prompt,answer,wrong,steps)
def projection_ex(sec,n,dim):
 a='\\(u+v=(2,6),\\;ku=(0,6)\\)' if dim==2 else '\\(u+v=(4,3,2),\\;ku=(-3,0,0)\\)'
 P='(0,u_2)' if dim==2 else '(u_1,0,0)'
 add(sec,n,[c('a','Compute the sum and scalar multiple.',a,[a.replace('6','3') if dim==2 else math('u+v=(2,-7,6),\\;ku=(-3,2,-4)'),math('u+v=0,\\;ku=0')],['Add each coordinate using the given addition.','Apply the special scalar multiplication, replacing the specified coordinates by zero.',a]),c('b','Why are both operations closed?','Both outputs are real ordered tuples of the required length.',['The operations always give the zero tuple.','Closure requires every coordinate to be nonzero.'],['Sums and scalar multiples of real entries are real.','Zero entries are permitted, so both outputs belong to the set.']),c('c','Which axioms follow from standard addition?','Axioms 1–5',['Axioms 6–10','Only Axiom 10'],['Addition is ordinary coordinatewise addition.','It is closed, commutative and associative; the zero tuple is an identity and coordinatewise negatives are inverses.']),c('d','Which identities establish Axioms 7–9?',math('k(u+v)=ku+kv,\\;(k+m)u=ku+mu,\\;k(mu)=(km)u'),[math('k(u+v)=ku+v,\\;(k+m)u=ku+m'),math('k(mu)=(k+m)u')],['Let '+math('P(u)='+P)+'. Then scalar multiplication is '+math('ku=kP(u)')+'.',math('P(u+v)=P(u)+P(v),\\;P^2=P')+'.',math('kP(u+v)=kP(u)+kP(v),\\;(k+m)P(u)=kP(u)+mP(u),\\;kP(mP(u))=kmP(u)')+'.']),c('e','Why does Axiom 10 fail?','The scalar 1 projects away coordinates, so it need not leave a vector unchanged.',['The zero tuple is absent.','Addition is not associative.'],[math('1u=P(u)')+'.','Choose a vector with a nonzero coordinate that is replaced by zero. Then '+math('1u\\ne u')+', so this is not a vector space.'])])
projection_ex(1,1,2)
add(1,3,[yn('answer','Is this a real vector space?',True,['The zero number belongs to the set; ordinary real addition and scalar multiplication are closed.','The real-number field laws give all ten vector-space axioms.'])])
add(1,4,[yn('answer','Is this a vector space?',True,[math('(a,0)+(b,0)=(a+b,0),\\;k(a,0)=(ka,0)')+'.','The set contains zero and is closed under both operations; the remaining axioms are inherited from '+math('R^2')+'.'])])
add(1,7,[c('answer','Identify the failed axiom.','Not a vector space: Axiom 8, distributivity over scalar addition, fails.',['It is a vector space.','Only Axiom 10 fails.'],['Take '+math('u=(1,0,0),\\;k=m=1')+'.',math('(k+m)u=(4,0,0)\\ne(2,0,0)=ku+mu')+'.','The other axioms hold because addition is standard, squares distribute over vector sums, and '+math('k^2m^2=(km)^2')+'.'])])
add(1,10,[yn('answer','Is this a vector space?',True,[math('0(1)=0')+'.',math('(f+g)(1)=f(1)+g(1)=0,\\;(kf)(1)=kf(1)=0')+'.','It is a subspace of the usual real-valued function space.'])])
add(1,17,[c('answer','Choose the necessary and sufficient condition.','The line passes through the origin.',['The line is horizontal.','The line has positive slope.'],['A vector space must contain its zero vector, so the origin must lie on the line.','Conversely, a line through the origin is '+math('\\{tv:t\\in R\\}')+' for a fixed nonzero direction '+math('v')+'.',math('t_1v+t_2v=(t_1+t_2)v,\\;k(tv)=(kt)v')+' prove closure, and the line contains zero.'])])
add(1,19,[c('answer','Rewrite the statement as a real-number identity.',math('\\frac1u=u^{-1}'),[math('-u=-1\\cdot u'),math('u+1=0')],['In Example 8, vector addition is multiplication and scalar multiplication is exponentiation.','The zero vector is the real number 1, so the additive inverse of '+math('u')+' is '+math('1/u')+'.','Scalar multiplication by '+math('-1')+' is '+math('u^{-1}')+', giving the stated identity.'])])
add(1,21,[c('answer','Choose the justifications for the three blanks, in order.','Associativity; additive inverse; additive identity.',['Commutativity; distributivity; scalar identity.','Additive identity; associativity; additive inverse.'],['Associativity changes '+math('(u+w)+(-w)')+' to '+math('u+[w+(-w)]')+'.','The inverse axiom gives '+math('w+(-w)=0')+'.','The identity axiom gives '+math('u+0=u')+' and '+math('v+0=v')+'.'])])
add(1,23,[c('answer','Which proof establishes the identity?',math('0u=(0+0)u=0u+0u;\\;\\text{cancel }0u'),[math('0u=u\\;\\text{by Axiom 10}'),math('0u=1u-0u')],['Distributivity over scalar addition gives '+math('0u=0u+0u')+'.','Add the additive inverse of '+math('0u')+' to both sides, and use associativity.','The result is '+math('0=0u')+'.'])])
add(1,25,[c('answer','Why is the singleton a vector space?','Every sum and scalar multiple is 0, so every axiom reduces to 0 = 0.',['It fails because it has no nonzero vector.','It fails scalar multiplication closure.'],['The specified operations are '+math('0+0=0')+' and '+math('k0=0')+'.','Zero is its own additive inverse; it is the identity.','All remaining identities involve only zero, proving every axiom.'])])
# Subspaces: every source part.
def sub(n,items):add(2,n,[yn(chr(97+i),'Is the set in part '+chr(97+i)+' a subspace?',v,st) for i,(v,st) in enumerate(items)])
sub(1,[(True,[math('(a,0,0)=a(1,0,0)')+'.','A span contains zero and is closed under linear combinations.']),(False,['The zero vector does not have second and third coordinates equal to 1.','A subspace must contain zero.']),(True,[math('(a,a+c,c)=a(1,1,0)+c(0,1,1)')+'.','This is a span and therefore a subspace.'])])
sub(3,[(True,['Zero is diagonal.','Adding or scaling diagonal matrices leaves every off-diagonal entry zero.']),(False,[math('A=\\operatorname{diag}(1,0,\\ldots,0),\\;B=\\operatorname{diag}(0,1,\\ldots,1)')+' are singular when '+math('n\\ge2')+'.','Their sum is the identity, so closure under addition fails. For '+math('n=1')+' the set is the zero subspace.']),(True,[math('\\operatorname{tr}(aA+bB)=a\\operatorname{tr}(A)+b\\operatorname{tr}(B)=0')+'.','Zero has trace zero, so the subspace test holds.']),(True,[math('(aA+bB)^T=aA^T+bB^T=aA+bB')+'.','The zero matrix is symmetric, and every linear combination remains symmetric.'])]);Q[key(2,3)]['reviewNotice']='Part b assumes n ≥ 2; for n = 1 the singular matrices form the zero subspace.'
sub(5,[(True,['The constant coefficient remains zero under addition and scaling.','The set is '+math('\\operatorname{span}\\{x,x^2,x^3\\}')+'.']),(True,['The coefficient condition is exactly '+math('p(1)=0')+'.',math('(ap+bq)(1)=ap(1)+bq(1)=0')+', and the zero polynomial qualifies.'])])
sub(7,[(True,[math('(af+bg)(0)=af(0)+bg(0)=0')+'.','The zero function belongs, establishing the subspace test.']),(False,['The zero function has value 0 at 0, not 1.','Thus the set is not a subspace.'])])
sub(9,[(True,['Every sequence is '+math('v(1,0,1,0,\\ldots)')+'.','The set is a span.']),(False,['The zero sequence is excluded by the entries fixed at 1.','Hence it is not a subspace.'])])
sub(11,[(True,['The second column is zero and stays zero under linear combinations.','The zero matrix belongs.']),(False,['The zero matrix does not have second column '+math('(1,1)^T')+'.','The set fails the zero-vector test.']),(False,['Multiplying the zero matrix by '+math('(1,-1)^T')+' gives zero, not '+math('(2,0)^T')+'.','The zero matrix is absent.'])])
sub(13,[(False,['The vector '+math('(1,1,1,1)')+' belongs.','Its double is '+math('(2,2,2,2)')+', whereas first coordinate 2 would require second coordinate 4; scaling closure fails.']),(True,[math('(a,0,b,0)=a(1,0,0,0)+b(0,0,1,0)')+'.','The set is a span.'])])
add(2,18,[c('answer','Which parameters prove closure under both operations?',math('kv_1=(kt_1)(a,b,c),\\;v_1+v_2=(t_1+t_2)(a,b,c)'),[math('kv_1=t_1(a,b,c),\\;v_1+v_2=t_1t_2(a,b,c)'),math('kv_1=(k+t_1)(a,b,c)')],['Write '+math('v_i=t_i(a,b,c)')+'.','Scaling multiplies the parameter by '+math('k')+'; addition adds parameters.','Both new parameters are real, and parameter zero gives the origin, proving the subspace test.'])])
add(2,23,[c('answer','List all possible kernels geometrically.','The origin; a line through the origin; a plane through the origin; all of three-dimensional space.',['Only a line or a plane.','Any line, any plane, or any sphere.'],['Three columns mean the domain is '+math('R^3')+'.','The kernel is a subspace, of dimension 0, 1, 2, or 3.','Those four dimensions give precisely the four listed geometries.'])])
add(2,25,[c('answer','Which representation proves the subspace claim?',math('\\operatorname{span}\\{\\cos(\\omega t),\\sin(\\omega t)\\}'),[math('\\{\\cos(\\omega t)+\\sin(\\omega t)\\}'),math('\\{c_1\\cos(\\omega t)+c_2:c_1c_2=1\\}')],['Sine and cosine are smooth for fixed '+math('\\omega')+'.','Setting both coefficients to zero gives zero.','Adding functions adds their two coefficients; multiplying a function by a scalar scales both coefficients. Thus the set is a subspace.'])])
# Computational helpers verify exact systems.
def solvefield(label,A,b,prompt='Choose the coefficients in the displayed generator order.'):
 A=M(A);b=M(b);r=A.rank();ar=A.row_join(b).rank()
 if r<ar:return c(label,prompt,'No solution (not in the span).',['A unique solution exists.','Every coefficient vector is a solution.'],['Build the coefficient equation '+math('Ac=b')+'.','The coefficient rank is '+str(r)+' and augmented rank is '+str(ar)+', so the system is inconsistent.'])
 sol,pars=A.gauss_jordan_solve(b);sol=sol.subs({p:0 for p in pars});assert A*sol==b
 return mc(label,prompt,sol,['Match coordinates to obtain '+math('Ac=b')+'.','Row reduction gives a valid coefficient vector '+mat(sol)+'.','Substitution gives '+mat(A*sol)+' exactly, confirming the linear combination.'])
add(3,1,[solvefield(l,M([[0,1],[-2,3],[2,-1]]),b,'Choose coefficients for '+math('au+bv')+', or identify no solution.') for l,b in zip('abc',[[2,2,2],[0,4,5],[0,0,0]])])
add(3,4,[solvefield(l,[[2,1,1],[1,0,2],[1,-1,0]],b) for l,b in zip('abc',[[1,1,0],[1,0,1],[1,1,1]])])
add(3,6,[solvefield(l,[[2,1,3],[1,-1,2],[4,3,5]],b) for l,b in zip('abcd',[[-9,-7,-15],[6,11,6],[0,0,0],[7,8,9]])])
add(3,8,[solvefield(l,M.hstack(M([2,1,0,3]),M([3,-1,5,2]),M([-1,0,2,1])),b) for l,b in zip('abcd',[[2,3,-7,3],[0,0,0,0],[1,1,1,1],[-4,6,-13,4]])])
def rankyn(label,A,target,prompt):
 A=M(A);r=A.rank();return yn(label,prompt,r==target,['Use the listed coordinate vectors as columns of '+mat(A)+'.','Row reduction gives '+mat(A.rref()[0])+'.','The rank is '+str(r)+', compared with the required dimension '+str(target)+'.'])
