add(3,19,[c('answer','Choose identities proving both span inclusions.',math('p_1=q_2,\\;p_2=\\frac12q_1+q_2;\\;q_1=2p_2-2p_1,\\;q_2=p_1'),[math('p_1=q_1,\\;p_2=q_2'),math('q_1=p_1+p_2,\\;q_2=p_2')],['Expand '+math('p_2-p_1=x')+'.','Thus '+math('q_1=2(p_2-p_1)')+' and '+math('q_2=p_1')+'.','Conversely '+math('p_1=q_2')+' and '+math('p_2=q_2+q_1/2')+', so each generating set lies in the other span.'])])
